SELECT no, content_id AS contentId, title, content_type_id AS contentTypeId, area_code AS sidoCode, si_gun_gu_code AS gugunCode, first_image1 AS firstImage1, first_image2 AS firstImage2, map_level AS mapLevel, latitude, longitude, tel, addr1, addr2, homepage, overview FROM attractions
AND area_code = #{sidoCode}
AND si_gun_gu_code = #{gugunCode}
AND content_type_id = #{contentTypeId}
AND title LIKE CONCAT('%', #{keyword}, '%')
